export function buscarNbsNota(numeroNota: number): NbsRow[] {
  return NBS_MOCK
    .filter(r => r.numero_nota === numeroNota)
    .sort((a, b) => a.cod_contabil.localeCompare(b.cod_contabil) || a.cod_centro_custo - b.cod_centro_custo);
}

